CREATE FUNCTION f1(a INT, INOUT b TEXT, OUT c DATE) LANGUAGE SQL AS $$SELECT b, CURRENT_DATE$$;
CREATE FUNCTION f2(x INT, y INT DEFAULT 5, z TEXT DEFAULT 'q') RETURNS INT LANGUAGE SQL IMMUTABLE STRICT AS 'SELECT x + y';
CREATE FUNCTION f3(VARIADIC xs INT[]) RETURNS INT LANGUAGE SQL AS 'SELECT 1';
CREATE FUNCTION f4(n INT) RETURNS TABLE(k INT, v TEXT) LANGUAGE SQL AS 'SELECT n, ''a''';
CREATE FUNCTION f5() RETURNS SETOF INT LANGUAGE SQL STABLE SECURITY DEFINER AS 'SELECT 1';
CREATE FUNCTION f6(INT, TEXT) RETURNS TEXT[] LANGUAGE SQL AS 'SELECT ARRAY[$2]';
CREATE FUNCTION f7(a INT, OUT r1 INT, OUT r2 INT) LANGUAGE SQL AS 'SELECT a, a';
CREATE PROCEDURE p1(IN a INT, INOUT b INT) LANGUAGE SQL AS 'SELECT 1';
CREATE PROCEDURE p2() LANGUAGE plpgsql AS $$BEGIN NULL; END$$;
CREATE FUNCTION tf() RETURNS TRIGGER LANGUAGE plpgsql AS $$BEGIN RETURN NEW; END$$;
SELECT routine_schema, routine_name, routine_type, data_type, type_udt_schema, type_udt_name, dtd_identifier, routine_body, routine_definition, external_name, external_language, parameter_style, is_deterministic, sql_data_access, is_null_call, sql_path, schema_level_routine, max_dynamic_result_sets, security_type, as_locator, is_udt_dependent FROM information_schema.routines WHERE routine_schema = 'public' ORDER BY routine_name;
SELECT ordinal_position, parameter_mode, is_result, as_locator, parameter_name, data_type, udt_schema, udt_name, dtd_identifier, parameter_default FROM information_schema.parameters WHERE specific_schema = 'public' ORDER BY specific_name, ordinal_position;
SELECT e.object_type, e.collection_type_identifier, e.data_type, e.udt_name, e.dtd_identifier FROM information_schema.element_types e WHERE e.object_schema = 'public' ORDER BY e.object_name, e.collection_type_identifier;
SELECT object_type, dtd_identifier FROM information_schema.data_type_privileges WHERE object_schema = 'public' ORDER BY object_name, dtd_identifier;
SELECT routine_name, data_type, type_udt_name, external_language, routine_body FROM information_schema.routines WHERE routine_schema = 'pg_catalog' AND routine_name IN ('lo_create', 'lo_import', 'date_bin', 'bthandler', 'int48eq') ORDER BY routine_name, data_type;
SELECT grantee, routine_name, privilege_type, is_grantable FROM information_schema.routine_privileges WHERE routine_schema = 'pg_catalog' AND routine_name IN ('lo_create', 'lo_import') ORDER BY routine_name, grantee;
CREATE TABLE t(a INT, b INT, c TEXT);
CREATE VIEW tv AS SELECT a, b FROM t;
CREATE FUNCTION tv_ins() RETURNS TRIGGER LANGUAGE plpgsql AS $$BEGIN RETURN NEW; END$$;
CREATE TRIGGER tr1 BEFORE INSERT OR UPDATE OF a, b ON t FOR EACH ROW EXECUTE FUNCTION tf();
CREATE TRIGGER tr2 AFTER DELETE ON t FOR EACH STATEMENT EXECUTE FUNCTION tf();
CREATE TRIGGER tr0 BEFORE INSERT ON t FOR EACH ROW EXECUTE FUNCTION tf('x', 'y');
CREATE TRIGGER tr3 AFTER UPDATE ON t FOR EACH ROW EXECUTE FUNCTION tf();
CREATE TRIGGER tvi INSTEAD OF INSERT OR UPDATE OR DELETE ON tv FOR EACH ROW EXECUTE FUNCTION tv_ins();
SELECT trigger_schema, trigger_name, event_manipulation, event_object_schema, event_object_table, action_order, action_condition, action_statement, action_orientation, action_timing, action_reference_old_table, action_reference_new_table, action_reference_old_row, action_reference_new_row, created FROM information_schema.triggers ORDER BY event_object_table, trigger_name, event_manipulation;
SELECT trigger_name, event_object_table, event_object_column FROM information_schema.triggered_update_columns ORDER BY trigger_name, event_object_column;
SELECT table_name, is_updatable, is_insertable_into, is_trigger_updatable, is_trigger_deletable, is_trigger_insertable_into FROM information_schema.views WHERE table_schema = 'public';
CREATE VIEW rv AS SELECT a + 1 AS x FROM t;
CREATE RULE rv_ins AS ON INSERT TO rv DO INSTEAD INSERT INTO t(a) VALUES (NEW.x);
CREATE RULE rv_del AS ON DELETE TO rv DO INSTEAD NOTHING;
SELECT table_name, is_updatable, is_insertable_into FROM information_schema.views WHERE table_name = 'rv';
SELECT table_name, is_insertable_into FROM information_schema.tables WHERE table_name = 'rv';
SELECT column_name, is_updatable FROM information_schema.columns WHERE table_name = 'rv';
CREATE SEQUENCE s1 START 5 INCREMENT 2;
CREATE SEQUENCE s2 AS SMALLINT MINVALUE -10 MAXVALUE 100 CYCLE;
CREATE SEQUENCE s3 AS INTEGER INCREMENT -1;
SELECT * FROM information_schema.sequences ORDER BY sequence_name;
